import java.util.*;class AlpineCleanupTest{public static void main(String[]a){int n=64;var e=new EnvironmentMap(EnvironmentMap.filled(n*n,800));e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];e.material=new byte[n*n];for(int x=10;x<28;x++){int i=20*n+x;e.height[i]=799;e.water[i]=800;e.river[i]=1;}int stray=45*n+45;e.height[stray]=799;e.water[stray]=800;e.river[stray]=1;var network=new RiverRibbon.Network(List.of(new RiverRibbon.Segment(new RiverRibbon.Point(10,20,1,800),new RiverRibbon.Point(28,20,1,800),1)));RiverPuddleCleanup.apply(e,n,62,64,network);if(e.river[20*n+15]==0||e.river[stray]!=0)throw new AssertionError("Planned stream removed or stray puddle retained");System.out.println("PASS: planned short summit stream survives; unrelated puddle removed");}}
